package com.performizeit.mjprof.model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;

public class SFNode {
    boolean  color = false;
    int count;
    String sf;
    HashMap<String,SFNode> children=     new HashMap<String,SFNode>();

    @Override
    public String toString() {
        if (count ==0) return "";
        if (count == 1) return toStringSingle();
        return toStringMulti(-1, new HashSet<Integer>(), count);
    }

    private String toStringSingle() {
        String indent = "       ";
        if (sf == null && children.size() >0  ) return   children.values().iterator().next().toStringSingle();
        if (children.size() ==0) return indent+sf;

        return children.values().iterator().next().toStringSingle() + "\n"+indent +sf;
    }

    private String CSI()
    {
        return (char)0x1b +"[";
    }
    private String GREEN() {
        if (!color) return "";
        return  CSI()+ "1;32m";
    }
    private String NC() {
        if (!color) return "";
        return CSI() + "0m";
    }

    public boolean isColor() {
        return color;
    }

    public void setColor(boolean color) {
        this.color = color;
    }

    public String toStringMulti(int lvl,HashSet<Integer> brkPts,int countall) {

        String a = "";
        if (sf != null) {     // we do not want to print the root node
            for (int i = 0; i < lvl; i++) {
                if (brkPts.contains(i)) {

                    a += GREEN() + "|" + NC();
                } else
                    a += " ";
            }
            String ch = "\\";
            if (children.size() > 1) {
                ch = "X";
                brkPts.add(lvl);
            }
            if (children.size() == 0) {
                ch = "V";
            }
            String bb = String.format("[%d/%d]", count, countall);
            a = String.format("%6.2f%%%10s", 100f * (float) count / countall, bb) + a + GREEN() + ch + NC() + " " + sf;
            a += "\n";

        }
        int t = 0;
        for(SFNode n: children.values())  {
            if (t == children.size()-1) {
                brkPts.remove(lvl);
            }
            t++;
            a  += n.toStringMulti(lvl + 1, brkPts, countall);
        }

        return a;
    }
    // Visit all chlidren of a node recursively with a ProfileVisitor
    public void visitChildren(ProfileVisitor pv, int level) {
        pv.visit(this, level);
        HashMap<String,SFNode> newChildren=     new HashMap<String,SFNode>();
        for (SFNode child : children.values()) {  // visit all childred
            child.visitChildren(pv, level + 1);
            newChildren.put(child.getStackFrame(),child);
        }
        children = newChildren;
    }
    // filter out children which do not match filter
    public void filterChildren(ProfileNodeFilter pnf,int level, Object context) {
        ArrayList<String> keysToRemove = new ArrayList<String>();

        for (String childKey : children.keySet()) {
            SFNode child =    children.get(childKey);
            boolean acceptNode = pnf.accept(child, level,context);
            child.filterChildren(pnf, level + 1,context);    // first filter out the children
            if ( !acceptNode) {
               keysToRemove.add(childKey);
            }
        }
        // if we are about to remove this child then we take all its children and fuse them to this node....
        for (String key: keysToRemove) {
            SFNode child = children.get(key);
            children.remove(key);
            for (String grandchildKey :child.children.keySet())  {
                if (children.get(grandchildKey) == null) {/// there is no child with grandchildKey
                    children.put(grandchildKey, child.children.get(grandchildKey));
                } else {
                    SFNode newChild = children.get(grandchildKey);
                    newChild.mergeToNode(child.children.get(grandchildKey));
                }

            }


        }
    }

    public void filterUpChildren(ProfileNodeFilter pnf,int level, Object context) {
        ArrayList<String> keysToRemove = new ArrayList<String>();

        for (String childKey : children.keySet()) {
        	SFNode child =    children.get(childKey);

        	boolean acceptNode = pnf.accept(child, level,context);
        	if (acceptNode ) {
        	//	child.filterUpChildren(pnf, level+1,context);    // first filter out the children
        	}
        	else{
        		keysToRemove.add(childKey);
        	}
        	child.filterUpChildren(pnf, level+1,context);  


        }


        // if we are about to remove this child then we take all its children and fuse them to this node....
        for (String key: keysToRemove) {
            SFNode child = children.get(key);
            children.remove(key);
            for (String grandchildKey :child.children.keySet())  {
                if (children.get(grandchildKey) == null) {/// there is no child with grandchildKey
                    children.put(grandchildKey, child.children.get(grandchildKey));
                } else {
                    SFNode newChild = children.get(grandchildKey);
                    newChild.mergeToNode(child.children.get(grandchildKey));
                }

            }

            System.out.println("+++++++++++++++ " + level + " " + child);

        }
    }

    public void filterDownChildren(ProfileNodeFilter pnf,int level, Object context) {
        ArrayList<String> keysToRemove = new ArrayList<String>();

        for (String childKey : children.keySet()) {
            SFNode child =    children.get(childKey);
          //  System.out.println("+++++++++++++++ " + level + " " + child);
            boolean acceptNode = pnf.accept(child, level,context);
            //if acceptNode==true we want to save it and all childern
            if ( !acceptNode) {
               keysToRemove.add(childKey);
               child.filterDownChildren(pnf, level + 1,context);    // first filter out the children
            }
        }
        // if we are about to remove this child then we take all its children and fuse them to this node....
        for (String key: keysToRemove) {
            SFNode child = children.get(key);
            children.remove(key);
            for (String grandchildKey :child.children.keySet())  {
                if (children.get(grandchildKey) == null) {/// there is no child with grandchildKey
                    children.put(grandchildKey, child.children.get(grandchildKey));
                } else {
                    SFNode newChild = children.get(grandchildKey);
                    newChild.mergeToNode(child.children.get(grandchildKey));
                }

            }


        }
    }


    public void mergeToNode(SFNode that) {
        this.count+= that.count;
        //merge children
        for (String key : that.children.keySet()) {
            SFNode thisChild = this.children.get(key);
            SFNode thatChild = that.children.get(key);
            if (thisChild != null) {
                thisChild.mergeToNode(thatChild);

            } else {
                children.put(key,thatChild.deepClone()) ;
            }
        }
    }

    public SFNode deepClone() {
        SFNode clone = new SFNode();
        clone.count = this.count;
        clone.sf =this.sf;
        for (String key : children.keySet()) {
            clone.children.put(key, children.get(key).deepClone());
        }
        return clone;
    }

    public String getStackFrame() {
        return sf;
    }

    public void setStackFrame(String sf) {
        this.sf = sf;
    }

    public int getNumChildren() {
        return children.size();
    }

    public int getCount() {
        return count;
    }

    public boolean isNull(){
    	return sf==null;
    }

	public boolean contains(String exp) {
		if(sf.contains(exp))
			return true;
		 for (String key : children.keySet()) {
			 SFNode thisChild = this.children.get(key);
			 if(thisChild.sf.contains(exp))
				 return true;
			 else
				 return thisChild.contains(exp);
	        }
		return false;
	}

    public int depthBelow() {
        int depthB = Integer.MAX_VALUE;
        for (SFNode child : children.values()) {
            int depthBnew = child.depthBelow()+1;
            if (depthBnew < depthB ) depthB = depthBnew;

        }
        if (depthB == Integer.MAX_VALUE) depthB = 0;
        return depthB;
    }
}

package com.performizeit.mjprof.model;

import com.performizeit.mjprof.parser.ThreadInfo;

import java.util.*;

import static com.performizeit.mjprof.parser.ThreadInfoProps.*;


public class ThreadInfoAggregator {
    private final List<String> props;
    HashSet<String> propsMap = new HashSet<String>();

    HashMap<List<Object>, ThreadInfo> aggregator = new HashMap<List<Object>, ThreadInfo>();

    public ThreadInfoAggregator(List<String> props) {
        this.props = props;
        for (String prop : props) propsMap.add(prop);
    }

    public void accumulateThreadInfo(ThreadInfo threadInfo) {
        ArrayList<Object> key = generateKey(threadInfo);
        ThreadInfo target = aggregator.get(key);
        if (target == null) {
            aggregator.put(key, threadInfo);
        } else {
            mergeProfiles(target, threadInfo);
            mergeCounts(target, threadInfo);
            mergeCPU(target, threadInfo);
            mergeNonKeyProps(target, threadInfo);
        }
    }
    public ArrayList<ThreadInfo> getAggrInfos() {
        return new ArrayList<ThreadInfo>(aggregator.values()) ;

    }

    private void mergeCounts(ThreadInfo target, ThreadInfo threadInfo) {
        Integer countTarget = (Integer) target.getVal(COUNT);
        Integer count = (Integer) threadInfo.getVal(COUNT);
        if (count == null) count = 1;
        if (countTarget == null) countTarget = 1;
        countTarget += count;
        target.setVal(COUNT, countTarget);
    }
    private double percentDouble(long nom,long denom) {
        return ((double)(nom*100*100/denom))/ 100.0;

    }
    private void mergeCPU(ThreadInfo target, ThreadInfo threadInfo) {
        Long cpuTarget = (Long) target.getVal(CPUNS);
        Long cpu = (Long) threadInfo.getVal(CPUNS);
        if (cpu != null && cpuTarget!= null) { // no cpu enrichment
            if (cpu == null) cpu = 0l;
            if (cpuTarget == null) cpuTarget = 0l;
            cpuTarget += cpu;
            target.setVal(CPUNS, cpuTarget);
        }

        Long wallTarget = (Long) target.getVal(WALL);
        Long wall = (Long) threadInfo.getVal(WALL);
        if (wall != null || wallTarget != null) {
            if (wall == null) wall = 0l;
            if (wallTarget == null) wallTarget = 0l;
            if (wallTarget < wall) wallTarget = wall;
            target.setVal(WALL, wallTarget);
        }
        if ((wall != null || wallTarget != null)  &&  (cpu != null && cpuTarget!= null) && wallTarget>0) {
            target.setVal(CPU_PREC, percentDouble(cpuTarget, (wallTarget * 1000 * 1000)));
        }
    }

    private void mergeProfiles(ThreadInfo target, ThreadInfo threadInfo) {
        Profile targetProfile = (Profile) target.getVal(STACK);
        Profile prof =   (Profile) threadInfo.getVal(STACK);
        if (prof == null) return;
        if (targetProfile == null) target.setVal(STACK,prof);
        targetProfile.addMulti(prof);
    }


    public void mergeNonKeyProps(ThreadInfo target, ThreadInfo threadInfo) {
        ArrayList<String> keys = new ArrayList<String>(threadInfo.getProps());
        for (String prop1 : keys) {
            if (prop1.equals(STACK) || prop1.equals(COUNT) || prop1.equals(CPUNS) ||
                    prop1.equals(WALL)|| prop1.equals(CPU_PREC) || propsMap.contains(prop1))
                continue; //    already merged to specially
            if (propsMap.contains(prop1)) continue; //     key properties are not merged

            Object valTarget = target.getVal(prop1);
            Object val = threadInfo.getVal(prop1);
            if (valTarget == null) {
                target.setVal(prop1, val);
            } else if (!val.equals(valTarget)) {   // we have more than one
                if (prop1.equals(DAEMON)) {
                    target.setVal(prop1, false);
                } if (prop1.equals(LOS)) {
                    target.setVal(prop1, "\t- *");
                } else {
                    target.setVal(prop1, "*");
                }
            }

        }


    }

    ArrayList<Object> generateKey(ThreadInfo threadInfo) {
        ArrayList<Object> key = new ArrayList<Object>();
        for (String prop : props) {
               key.add(threadInfo.getVal(prop));
        }
        return key;

    }


}

