            }
            for (int k = 1; k <= ewah.length; ++k) {
                EWAHCompressedBitmap32[] shortewah = new EWAHCompressedBitmap32[k];
                System.arraycopy(ewah, 0, shortewah, 0, k);
                assertAndEquals(shortewah);
            }
        }
    }

