package com.marginallyclever.convenience;


import java.awt.Color;
import java.util.Objects;


/**
 * RGB color class
 * @author Dan Royer
 *
 */
public class ColorRGB {
  public int red = 0;
  public int green = 0;
  public int blue = 0;

  public ColorRGB(int r, int g, int b) {
    red = r;
    green = g;
    blue = b;
  }

  public ColorRGB(ColorRGB x) {
    set(x);
  }

  public ColorRGB(int pixel) {
    int r = ((pixel >> 16) & 0xff);
    int g = ((pixel >> 8) & 0xff);
    int b = ((pixel) & 0xff);
    set(r, g, b);
  }

  public ColorRGB(Color c) {
    red = c.getRed();
    green = c.getGreen();
    blue = c.getBlue();
  }

  public int toInt() {
    return ((red & 0xff) << 16) | ((green & 0xff) << 8) | (blue & 0xff);
  }

  public ColorRGB set(ColorRGB x) {
    red = x.red;
    green = x.green;
    blue = x.blue;
    return this;
  }

  public void set(int r, int g, int b) {
    red = r;
    green = g;
    blue = b;
  }

  public ColorRGB sub(ColorRGB x) {
    red -= x.red;
    green -= x.green;
    blue -= x.blue;
    return this;
  }

  public ColorRGB add(ColorRGB x) {
    red += x.red;
    green += x.green;
    blue += x.blue;
    return this;
  }

  public ColorRGB mul(double f) {
    red *= f;
    green *= f;
    blue *= f;
    return this;
  }

  public float diff(ColorRGB o) {
    int rDiff = o.red - this.red;
    int gDiff = o.green - this.green;
    int bDiff = o.blue - this.blue;
    int distanceSquared = rDiff * rDiff + gDiff * gDiff + bDiff * bDiff;
    return (float) Math.sqrt(distanceSquared);
  }

  public boolean isEqualTo(ColorRGB o) {
	  if(o.red - this.red != 0) return false;
	  if(o.green - this.green != 0) return false;
	  if(o.blue - this.blue != 0) return false;
	  return true;
  }

  public String toString() {
    return "(" + red + "," + green + "," + blue + ")";
  }

  public int getRed() { return red; }
  public int getGreen() { return green; }
  public int getBlue() { return blue; }

  @Override
  public boolean equals(Object o) {
    if (this == o) return true;
    if (o == null || getClass() != o.getClass()) return false;
    ColorRGB colorRGB = (ColorRGB) o;
    return red == colorRGB.red && green == colorRGB.green && blue == colorRGB.blue;
  }

  @Override
  public int hashCode() {
    return Objects.hash(red, green, blue);
  }
}

package com.marginallyclever.makelangelo.makeArt.io.vector;

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.security.InvalidParameterException;
import java.util.ArrayList;

import javax.swing.filechooser.FileNameExtensionFilter;

import com.marginallyclever.makelangelo.turtle.Turtle;

public class TurtleFactory {
	private static TurtleLoader [] loaders = {
		new LoadDXF(),
		new LoadGCode(),
		new LoadScratch2(),
		new LoadScratch3(),
		new LoadSVG(),
	};

	private static TurtleSaver [] savers = {
		new SaveDXF(),
		new SaveSVG(),
	};

	public static Turtle load(String filename) throws Exception {
		if(filename == null || filename.trim().length()==0) throw new InvalidParameterException("filename cannot be empty");

		for( TurtleLoader loader : loaders ) {
			if(isValidExtension(filename,loader.getFileNameFilter())) {
				FileInputStream in = new FileInputStream(filename);
				Turtle result = loader.load(in);
				in.close();
				return result;
			}
		}
		throw new Exception("TurtleFactory could not load '"+filename+"'.");
	}

	private static boolean isValidExtension(String filename, FileNameExtensionFilter filter) {
		String [] extensions = filter.getExtensions();
		for( String e : extensions ) {
			if(filename.endsWith(e)) return true;
		}
		return false;
	}

	public static ArrayList<FileNameExtensionFilter> getLoadExtensions() {
		ArrayList<FileNameExtensionFilter> filters = new ArrayList<FileNameExtensionFilter>();
		for( TurtleLoader loader : loaders ) {
			filters.add( loader.getFileNameFilter() );
		}
		return filters;
	}

	public static ArrayList<FileNameExtensionFilter> getSaveExtensions() {
		ArrayList<FileNameExtensionFilter> filters = new ArrayList<FileNameExtensionFilter>();
		for( TurtleSaver saver : savers ) {
			filters.add( saver.getFileNameFilter() );
		}
		return filters;
	}

	public static void save(Turtle turtle,String filename) throws Exception {
		if(filename == null || filename.trim().length()==0) throw new InvalidParameterException("filename cannot be empty");

		for( TurtleSaver saver : savers ) {
			if(isValidExtension(filename,saver.getFileNameFilter())) {
				FileOutputStream out = new FileOutputStream(filename); 
				saver.save(out,turtle);
				out.close();
				return;
			}
		}
		throw new Exception("TurtleFactory could not save '"+filename+"'.");
	}
}

