     *
     * @param data  the data
     * @param start the start
     * @param end   the end
     * @return long version of the data
     */
    public static long convertBigEndianBytesToLong(final byte[] data, final int start, final int end) {

        long offset = 0;
        for (int x = start; x < end; ++x) {
            offset = offset << 8;
            offset |= (data[x] & 0xFFL);
        }

        return offset;
    }
