 */
class NullMatcher<T> extends DiagnosingCustomisableMatcher<T> {
	public NullMatcher(T expected) {
		super(expected);
	}

    @Override
    protected boolean matches(Object actual, Description mismatchDescription) {
        if (actual != null) {
