                try
                {
                    getLogger().log( Level.INFO, "Disconnecting {0} connections", connections.size() );
                    for ( UserConnection user : connections.values() )
                    {
                        user.disconnect( reason );
                    }
                } finally
                {
                    connectionLock.readLock().unlock();
                }

                try
                {
                    Thread.sleep( 500 );
                } catch ( InterruptedException ex )
                {
                }

                if ( reconnectHandler != null )
                {
                    getLogger().info( "Saving reconnect locations" );
                    reconnectHandler.save();
                    reconnectHandler.close();
                }
                saveThread.cancel();
                metricsThread.cancel();

                // TODO: Fix this shit
                getLogger().info( "Disabling plugins" );
                for ( Plugin plugin : Lists.reverse( new ArrayList<>( pluginManager.getPlugins() ) ) )
                {
                    try
                    {
                        plugin.onDisable();
                        for ( Handler handler : plugin.getLogger().getHandlers() )
                        {
                            handler.close();
                        }
                    } catch ( Throwable t )
                    {
                        getLogger().log( Level.SEVERE, "Exception disabling plugin " + plugin.getDescription().getName(), t );
                    }
                    getScheduler().cancel( plugin );
                    plugin.getExecutorService().shutdownNow();
                }

                getLogger().info( "Closing IO threads" );
                bossEventLoopGroup.shutdownGracefully(); //BotFilter
                workerEventLoopGroup.shutdownGracefully(); //BotFilter
                while ( true ) //BotFilter
                {
                    try
                    {
                        bossEventLoopGroup.awaitTermination( Long.MAX_VALUE, TimeUnit.NANOSECONDS ); //BotFilter
                        workerEventLoopGroup.awaitTermination( Long.MAX_VALUE, TimeUnit.NANOSECONDS ); //BotFilter
                        break;
                    } catch ( InterruptedException ignored )
                    {
                    }
                }

                getLogger().info( "Thank you and goodbye" );
                // Need to close loggers after last message!
                for ( Handler handler : getLogger().getHandlers() )
                {
                    handler.close();
                }
                System.exit( 0 );
            }
        }.start();
    }

    /**
     * Broadcasts a packet to all clients that is connected to this instance.
     *
     * @param packet the packet to send
     */
    public void broadcast(DefinedPacket packet)
    {
        connectionLock.readLock().lock();
        try
        {
            for ( UserConnection con : connections.values() )
            {
                con.unsafe().sendPacket( packet );
            }
        } finally
        {
            connectionLock.readLock().unlock();
        }
    }

    @Override
    public String getName()
    {
        return "BotFilter"; //BotFilter
    }

    @Override
