		byte[] code = Arrays.copyOfRange(resp, resp.length - 2, resp.length);
		assertArrayEquals(success, code);
		short offs = 1;
		offs += resp[offs];
		offs += 3;
		offs += resp[offs];
		offs += 5;
		offs += resp[offs];
		offs += 2;
		offs += resp[offs];
		offs += 2;
		offs += resp[offs];
		offs += 2;
		offs += resp[offs];
		offs += 7;
		result[0] = resp[offs++];
		result[1] = resp[offs++];
		result[2] = resp[offs++];
		return result;
	}

